<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class BookingSlot extends Model { protected $fillable=['puja_id','slot_date','start_time','end_time','capacity','reserved_count','is_active']; protected function casts():array{return ['slot_date'=>'date','is_active'=>'boolean'];} public function puja(){return $this->belongsTo(Puja::class);} public function hasAvailability():bool{return $this->is_active && $this->reserved_count < $this->capacity;} }
